/**
 * Reply to RPC commands (replyToCommand)
 * Replies to server originated RPC command identified by 'requestId' parameter. The response is arbitrary JSON.
 *
 * The API call is designed to be used by device firmware and requires device access token ('deviceToken'). It is not recommended to use this API call by third-party scripts, rule-engine or platform widgets (use 'Telemetry Controller' instead).
 *
 */
export const replyToCommand = <ThrowOnError extends boolean = false>(options: Options<ReplyToCommandData, ThrowOnError>) => {
    return (options?.client ?? client).post<ReplyToCommandResponse, ReplyToCommandError, ThrowOnError>({
        ...options,
        url: '/api/v1/{deviceToken}/rpc/{requestId}'
    });
};

/**
 * Get Device Software (getSoftware)
 * Downloads the current software package.When the platform initiates software update, it informs the device by updating the 'sw_title', 'sw_version', 'sw_checksum' and 'sw_checksum_algorithm' shared attributes.The 'sw_title' and 'sw_version' parameters must be supplied in this request to double-check that the software that device is downloading matches the software it expects to download. This is important, since the administrator may change the software assignment while device is downloading the software.
 *
 * Optional 'chunk' and 'size' parameters may be used to download the software in chunks. For example, device may request first 16 KB of software using 'chunk'=0 and 'size'=16384. Next 16KB using 'chunk'=1 and 'size'=16384. The last chunk should have less bytes then requested using 'size' parameter.
 *
 * The API call is designed to be used by device firmware and requires device access token ('deviceToken'). It is not recommended to use this API call by third-party scripts, rule-engine or platform widgets (use 'Telemetry Controller' instead).
 *
 */
export const getSoftware = <ThrowOnError extends boolean = false>(options: Options<GetSoftwareData, ThrowOnError>) => {
    return (options?.client ?? client).get<GetSoftwareResponse, GetSoftwareError, ThrowOnError>({
        ...options,
        url: '/api/v1/{deviceToken}/software'
    });
};

/**
 * Post time series data (postTelemetry)
 * Post time series data on behalf of device.
 * Example of the request: The request payload is a JSON document with three possible formats:
 *
 * Simple format without timestamp. In such a case, current server time will be used:
 *
 *
 *
 * ```json
 * {
 * "stringKey":"value1",
 * "booleanKey":true,
 * "doubleKey":42.0,
 * "longKey":73,
 * "jsonKey": {
 * "someNumber": 42,
 * "someArray": [1,2,3],
 * "someNestedObject": {"key": "value"}
 * }
 * }
 * ```
 *
 *
 *
 * Single JSON object with timestamp:
 *
 *
 *
 * ```json
 * {"ts":1634712287000,"values":{"temperature":26, "humidity":87}}
 * ```
 *
 *
 *
 * JSON array with timestamps:
 *
 *
 *
 * ```json
 * [
 * {"ts":1634712287000,"values":{"temperature":26, "humidity":87}},
 * {"ts":1634712588000,"values":{"temperature":25, "humidity":88}}
 * ]
 * ```
 *
 * The API call is designed to be used by device firmware and requires device access token ('deviceToken'). It is not recommended to use this API call by third-party scripts, rule-engine or platform widgets (use 'Telemetry Controller' instead).
 *
 */
export const postTelemetry = <ThrowOnError extends boolean = false>(options: Options<PostTelemetryData, ThrowOnError>) => {
    return (options?.client ?? client).post<PostTelemetryResponse, PostTelemetryError, ThrowOnError>({
        ...options,
        url: '/api/v1/{deviceToken}/telemetry'
    });
};

