/**
 * Get Customer Device Infos (getCustomerDeviceInfos)
 * Returns a page of devices info objects assigned to customer. You can specify parameters to filter the results. The result is wrapped with PageData object that allows you to iterate over result set using pagination. See response schema for more details. Device Info is an extension of the default Device object that contains information about the assigned customer name and device profile name.
 *
 * Available for users with 'TENANT_ADMIN' or 'CUSTOMER_USER' authority.
 */
export const getCustomerDeviceInfos = <ThrowOnError extends boolean = false>(options: Options<GetCustomerDeviceInfosData, ThrowOnError>) => {
    return (options?.client ?? client).get<GetCustomerDeviceInfosResponse, GetCustomerDeviceInfosError, ThrowOnError>({
        ...options,
        url: '/api/customer/{customerId}/deviceInfos'
    });
};

